import pyomo.environ as pyo

DATA = {
    "products": ["bagels", "croissants"],
    "resources": ["oven", "chef"],
    "usage": {
        ("bagels", "oven"): 2.0,
        ("bagels", "chef"): 0.25,
        ("croissants", "oven"): 1.0,
        ("croissants", "chef"): 2.0,
    },
    "availability": {"oven": 70.0, "chef": 32.0},
    "profit": {"bagels": 20.0, "croissants": 40.0},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.PRODUCTS = pyo.Set(initialize=d["products"])
    model.RESOURCES = pyo.Set(initialize=d["resources"])

    model.x = pyo.Var(
        model.PRODUCTS, within=pyo.NonNegativeReals, bounds=(0, None)
    )

    def profit_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.PRODUCTS)

    model.obj = pyo.Objective(expr=profit_rule, sense=pyo.maximize)

    # One resource-capacity constraint per resource (oven and chef),
    # enforced as equality because the problem states all capacity is used.
    def resource_capacity_rule(m, r):
        return sum(
            d["usage"][(p, r)] * m.x[p] for p in m.PRODUCTS
        ) == d["availability"][r]

    model.resource_capacity = pyo.Constraint(
        model.RESOURCES, rule=resource_capacity_rule
    )

    return model
